using System.Globalization; using System.Windows; using System.Windows.Controls; using System.Windows.Input; using System.Text.Json; using Microsoft.Win32; using DataMaker.Refactored.Services; using DataMaker.Refactored.Models; using DataMaker.Refactored.ViewModels;
namespace DataMaker.Refactored.Views;
public partial class RefactoredWindow : Window
{
 public MainViewModel ViewModel {get;}=new(); FieldConfig? selected;
 public RefactoredWindow()
 {
  InitializeComponent();
  DataContext=ViewModel;
  var path=ConfigPath;
  if(File.Exists(path))
  {
   try
   {
    ViewModel.ReplaceConfig(new ConfigService().Load(path));
   }
   catch(Exception ex)
   {
    var backup=path+".bak";
    try
    {
     if(File.Exists(backup)) ViewModel.ReplaceConfig(new ConfigService().Load(backup));
     else throw;
    }
    catch
    {
     MessageBox.Show($"读取上次配置失败：{ex.Message}\n配置文件：{path}","配置恢复失败",MessageBoxButton.OK,MessageBoxImage.Warning);
    }
   }
  }
  RefreshGroups();
  SubtaskCountBox.Text=ViewModel.Config.Groups.Count.ToString();
  RefreshTemplates();
  FailurePolicyBox.SelectedIndex=ViewModel.Config.FailurePolicy==FailurePolicy.Stop?1:0;
  RetryBox.Text=ViewModel.Config.RetryCount.ToString();
 }
 string TemplateDirectory=>Path.Combine(string.IsNullOrWhiteSpace(ViewModel.Config.StorageDirectory)?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"DataMaker"):ViewModel.Config.StorageDirectory,"Templates");
 void RefreshTemplates(){Directory.CreateDirectory(TemplateDirectory);TemplateList.ItemsSource=new TemplateService().List(TemplateDirectory).Select(Path.GetFileName).Where(x=>x is not null).ToList();}
 void RefreshTemplate_Click(object s,RoutedEventArgs e)=>RefreshTemplates();
 void DeleteTemplate_Click(object s,RoutedEventArgs e){if(TemplateList.SelectedItem is string name){var path=Path.Combine(TemplateDirectory,name);new TemplateService().Delete(path);RefreshTemplates();}}
 void CopyTemplate_Click(object s,RoutedEventArgs e){if(TemplateList.SelectedItem is not string name)return;var path=Path.Combine(TemplateDirectory,name);var target=Path.Combine(TemplateDirectory,Path.GetFileNameWithoutExtension(path)+"_copy.json");File.Copy(path,target,true);RefreshTemplates();}
 void RenameTemplate_Click(object s,RoutedEventArgs e){if(TemplateList.SelectedItem is not string name)return;var path=Path.Combine(TemplateDirectory,name);var target=Path.Combine(TemplateDirectory,Path.GetFileNameWithoutExtension(path)+"_renamed.json");File.Move(path,target,true);RefreshTemplates();}
 void CloseStatus_Click(object s,RoutedEventArgs e){TestPointList.Visibility=Visibility.Collapsed;}
 void Generate_Click(object s,RoutedEventArgs e){TestPointList.Visibility=Visibility.Visible;if(ViewModel.GenerateCommand.CanExecute(null))ViewModel.GenerateCommand.Execute(null);}
 void TestPointList_DoubleClick(object s,MouseButtonEventArgs e){var source=e.OriginalSource as DependencyObject;while(source is not null&&source is not ListViewItem)source=System.Windows.Media.VisualTreeHelper.GetParent(source);if(source is not ListViewItem)return;if(TestPointList.SelectedItem is not TestPointResult p)return;var point=e.GetPosition(TestPointList);var openInput=point.X<TestPointList.ActualWidth/2;var path=openInput?p.InputPath:p.OutputPath;if(!File.Exists(path)){MessageBox.Show($"文件不存在：{path}",openInput?"打开输入文件":"打开输出文件",MessageBoxButton.OK,MessageBoxImage.Information);return;}System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(path){UseShellExecute=true});}
 void TemplateList_DoubleClick(object s,MouseButtonEventArgs e){if(TemplateList.SelectedItem is not string name)return;var path=Path.Combine(TemplateDirectory,name);ViewModel.ReplaceConfig(new TemplateService().Load(path));FieldList.Items.Refresh();RefreshGroups();}
 static string ConfigPath=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"DataMaker","last-project.json");
 void Window_Closing(object? sender,System.ComponentModel.CancelEventArgs e){SaveLastConfig();}
 void RebindConfig(){var data=DataContext;DataContext=null;DataContext=data;}
 void SaveLastConfig(){try{var dir=Path.GetDirectoryName(ConfigPath)!;Directory.CreateDirectory(dir);if(File.Exists(ConfigPath))File.Copy(ConfigPath,ConfigPath+".bak",true);new ConfigService().Save(ViewModel.Config,ConfigPath);}catch(Exception ex){ViewModel.Messages.Add(new LogEntry{Text=$"保存配置失败：{ex.Message}",Level="Error"});}}
 void BrowseSource_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="C++ 源文件|*.cpp;*.cc;*.cxx"};if(d.ShowDialog()==true){ViewModel.Config.SourcePath=d.FileName;RebindConfig();SaveLastConfig();}}

 void BrowseGpp_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="g++.exe|g++.exe"};if(d.ShowDialog()==true){ViewModel.Config.MingwPath=d.FileName;RebindConfig();SaveLastConfig();}}
 void BrowseStorage_Click(object s,RoutedEventArgs e){var d=new OpenFolderDialog{Title="选择数据存储目录"};if(d.ShowDialog()==true){ViewModel.Config.StorageDirectory=d.FolderName;RebindConfig();SaveLastConfig();RefreshTemplates();}}
 void BrowseZip_Click(object s,RoutedEventArgs e){var d=new SaveFileDialog{Filter="ZIP 文件|*.zip",FileName="data.zip"};if(d.ShowDialog()==true){ViewModel.Config.ZipPath=d.FileName;RebindConfig();SaveLastConfig();}}
 void FailurePolicy_Changed(object s,SelectionChangedEventArgs e){if(ViewModel is not null)ViewModel.Config.FailurePolicy=FailurePolicyBox.SelectedIndex==1?FailurePolicy.Stop:FailurePolicy.Continue;}
 void Retry_Changed(object s,TextChangedEventArgs e){if(int.TryParse(RetryBox.Text,out var n))ViewModel.Config.RetryCount=Math.Max(0,n);}
 void LoadTemplate_Click(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="DataMaker 模板|*.json"};if(d.ShowDialog()==true){ViewModel.ReplaceConfig(new TemplateService().Load(d.FileName));FieldList.Items.Refresh();RefreshGroups();}}
 void SaveTemplate_Click(object s,RoutedEventArgs e){var d=new SaveFileDialog{Filter="DataMaker 模板|*.json",FileName="template.json"};if(d.ShowDialog()==true){var service=new TemplateService();service.Save(ViewModel.Config,d.FileName);Directory.CreateDirectory(TemplateDirectory);var preset=Path.Combine(TemplateDirectory,Path.GetFileName(d.FileName));if(!string.Equals(Path.GetFullPath(d.FileName),Path.GetFullPath(preset),StringComparison.OrdinalIgnoreCase))File.Copy(d.FileName,preset,true);RefreshTemplates();}}
 void AddInt_Click(object s,RoutedEventArgs e)=>Add(new IntField()); void AddFloat_Click(object s,RoutedEventArgs e)=>Add(new FloatField()); void AddString_Click(object s,RoutedEventArgs e)=>Add(new StringField()); void AddArray_Click(object s,RoutedEventArgs e)=>Add(new ArrayField()); void AddTree_Click(object s,RoutedEventArgs e)=>Add(new TreeField()); void AddGraph_Click(object s,RoutedEventArgs e)=>Add(new GraphField());
 void ApplySubtaskCount_Click(object s,RoutedEventArgs e){if(!int.TryParse(SubtaskCountBox.Text,out var count)||count<0){MessageBox.Show("Subtask 数量必须是大于等于 0 的整数。","Subtask",MessageBoxButton.OK,MessageBoxImage.Warning);return;}if(count==0){ViewModel.Config.Groups.Clear();RefreshGroups();return;}while(ViewModel.Config.Groups.Count<count)ViewModel.Config.Groups.Add(new GroupConfig{Name=$"Subtask {ViewModel.Config.Groups.Count+1}",From=0,To=0});while(ViewModel.Config.Groups.Count>count)ViewModel.Config.Groups.RemoveAt(ViewModel.Config.Groups.Count-1);for(var i=0;i<ViewModel.Config.Groups.Count;i++)ViewModel.Config.Groups[i].Name=$"Subtask {i+1}";RefreshGroups();}
 void AddGroup_Click(object s,RoutedEventArgs e){if(ViewModel.Config.Groups.Count==0){MessageBox.Show("请先设置 Subtask 子任务数量。数量为 0 表示不分组。","Subtask",MessageBoxButton.OK,MessageBoxImage.Information);return;}if(ViewModel.Config.Groups.Count(g=>g.From>0&&g.To>0)>=ViewModel.Config.Groups.Count){MessageBox.Show("当前 Subtask 数量的区间已经全部设置。","Subtask",MessageBoxButton.OK,MessageBoxImage.Information);return;}if(!int.TryParse(GroupFromBox.Text,out var from)||!int.TryParse(GroupToBox.Text,out var to)||to<from)return;if(from<1||to>ViewModel.Config.TestCount||ViewModel.Config.Groups.Any(g=>from<=g.To&&to>=g.From)){MessageBox.Show("子任务区间必须在测试点范围内且不能重叠。","添加子任务",MessageBoxButton.OK,MessageBoxImage.Warning);return;}var group=ViewModel.Config.Groups.First(g=>g.From<=0||g.To<=0);group.From=from;group.To=to;RefreshGroups();}
 void DeleteGroup_Click(object s,RoutedEventArgs e){var index=GroupList.SelectedIndex;if(index>=0&&index<ViewModel.Config.Groups.Count){ViewModel.Config.Groups.RemoveAt(index);RefreshGroups();}}
 void RefreshGroups(){GroupList.ItemsSource=null;GroupList.ItemsSource=ViewModel.Config.Groups.Select(g=>$"{g.Name} ({g.From}-{g.To})").ToList();RefreshOverrideMatrix();}
 void GroupList_SelectionChanged(object s,SelectionChangedEventArgs e){var index=GroupList.SelectedIndex;if(index>=0&&index<ViewModel.Config.Groups.Count){var g=ViewModel.Config.Groups[index];GroupFromBox.Text=g.From>0?g.From.ToString():"";GroupToBox.Text=g.To>0?g.To.ToString():"";}RefreshOverrideMatrix();}
 void GroupRange_Changed(object s,RoutedEventArgs e){var index=GroupList.SelectedIndex;if(index<0||index>=ViewModel.Config.Groups.Count)return;if(!int.TryParse(GroupFromBox.Text,out var from)||!int.TryParse(GroupToBox.Text,out var to)||from<1||to<from||to>ViewModel.Config.TestCount){return;}var g=ViewModel.Config.Groups[index];if(ViewModel.Config.Groups.Where((x,i)=>i!=index).Any(x=>x.From>0&&x.To>0&&from<=x.To&&to>=x.From)){MessageBox.Show("Subtask 区间不能重叠。","Subtask",MessageBoxButton.OK,MessageBoxImage.Warning);return;}g.From=from;g.To=to;RefreshGroups();GroupList.SelectedIndex=index;SaveLastConfig();}
 void OverrideMatrix_DoubleClick(object s,MouseButtonEventArgs e){if(OverrideMatrix.SelectedItem is not System.Data.DataRowView row)return;var column=OverrideMatrix.CurrentColumn;if(column is null||column.DisplayIndex==0)return;var fieldName=row[0]?.ToString();if(string.IsNullOrWhiteSpace(fieldName))return;var gi=column.DisplayIndex-1;if(gi<0||gi>=ViewModel.Config.Groups.Count)return;var field=ViewModel.Config.Fields.FirstOrDefault(x=>x.Name==fieldName);if(field is null)return;var initial=groupText(ViewModel.Config.Groups[gi],fieldName);if(string.IsNullOrWhiteSpace(initial))initial=globalText(field);var dialog=new OverrideEditorWindow(field,initial){Owner=this};if(dialog.ShowDialog()==true){var g=ViewModel.Config.Groups[gi];if(string.IsNullOrWhiteSpace(dialog.ResultText))g.TypedOverrides.Remove(fieldName);else ApplyOverrideText(g,field,dialog.ResultText);RefreshOverrideMatrix();SaveLastConfig();}}
 string groupText(GroupConfig g,string name)=>g.TypedOverrides.TryGetValue(name,out var v)?FormatOverride(v):"";
 string globalText(FieldConfig f)=>f switch{IntField x=>$"min={x.Min};max={x.Max}",FloatField x=>$"min={x.Min};max={x.Max};precision={x.Precision}",StringField x=>$"length={x.Length};minLength={x.MinLength};maxLength={x.MaxLength};charset={x.Charset};pattern={x.Pattern}",ArrayField x=>$"length={x.Length};min={x.Min};max={x.Max};precision={x.Precision};pattern={x.Pattern};sort={x.SortOrder};unique={x.Unique}",TreeField x=>$"nodes={x.Nodes};shape={x.Shape};root={x.Root};weightMin={x.WeightMin};weightMax={x.WeightMax}",GraphField x=>$"nodes={x.Nodes};edges={x.Edges};shape={x.Shape};density={x.Density};weightMin={x.WeightMin};weightMax={x.WeightMax}",_=>""};
 void ApplyOverrideText(GroupConfig g,FieldConfig f,string text){var parsed=OverrideTextService.Parse(f,text);if(parsed is null)g.TypedOverrides.Remove(f.Name);else g.TypedOverrides[f.Name]=parsed;}
 void OverrideMatrix_CellEditEnding(object s,DataGridCellEditEndingEventArgs e){if(e.EditAction!=DataGridEditAction.Commit||e.Row.Item is not System.Data.DataRowView row||e.Column.DisplayIndex==0)return;var fieldName=row[0]?.ToString();if(string.IsNullOrWhiteSpace(fieldName))return;var groupIndex=e.Column.DisplayIndex-1;if(groupIndex<0||groupIndex>=ViewModel.Config.Groups.Count)return;var text=(e.EditingElement as TextBox)?.Text?.Trim()??"";var group=ViewModel.Config.Groups[groupIndex];var field=ViewModel.Config.Fields.FirstOrDefault(x=>x.Name==fieldName);if(field is null)return;var parsed=OverrideTextService.Parse(field,text);if(parsed is null)group.TypedOverrides.Remove(fieldName);else group.TypedOverrides[fieldName]=parsed;}
 static string FormatOverride(FieldOverrideBase value)=>OverrideTextService.ToText(value);
 void RefreshOverrideMatrix(){var table=new System.Data.DataTable();table.Columns.Add("字段");foreach(var g in ViewModel.Config.Groups)table.Columns.Add($"{g.Name} ({g.From}-{g.To})");foreach(var f in ViewModel.Config.Fields){var row=table.NewRow();row[0]=f.Name;for(var i=0;i<ViewModel.Config.Groups.Count;i++){var g=ViewModel.Config.Groups[i];var text=g.TypedOverrides.TryGetValue(f.Name,out var typed)?FormatOverride(typed):"(继承全局)";row[i+1]=text;}table.Rows.Add(row);}OverrideMatrix.ItemsSource=table.DefaultView;}
 void Add(FieldConfig f){f.Name=$"field{ViewModel.Config.Fields.Count+1}";ViewModel.Config.Fields.Add(f);FieldList.Items.Refresh();FieldList.SelectedItem=f;RefreshOverrideMatrix();SaveLastConfig();}
 void Delete_Click(object s,RoutedEventArgs e){if(FieldList.SelectedItem is not FieldConfig f)return;var references=ViewModel.Config.Fields.Where(x=>x!=f).Where(x=>ValidationService.ReferencedVariables(x).Contains(f.Name)).Select(x=>x.Name).ToList();if(references.Count>0){MessageBox.Show($"字段 {f.Name} 被字段 {string.Join(", ",references)} 的表达式引用，不能删除。","删除字段",MessageBoxButton.OK,MessageBoxImage.Warning);return;}ViewModel.Config.Fields.Remove(f);foreach(var g in ViewModel.Config.Groups)g.TypedOverrides.Remove(f.Name);FieldList.Items.Refresh();EditorPanel.Children.Clear();RefreshOverrideMatrix();SaveLastConfig();}
 void Copy_Click(object s,RoutedEventArgs e){if(FieldList.SelectedItem is not FieldConfig f)return;var json=JsonSerializer.Serialize<FieldConfig>(f);var copy=JsonSerializer.Deserialize<FieldConfig>(json)!;copy.Name=f.Name+"_copy";var index=ViewModel.Config.Fields.IndexOf(f);ViewModel.Config.Fields.Insert(index+1,copy);FieldList.Items.Refresh();FieldList.SelectedItem=copy;RefreshOverrideMatrix();SaveLastConfig();}
 Point dragStart;
 void FieldList_MouseDown(object s,MouseButtonEventArgs e)=>dragStart=e.GetPosition(FieldList);
 void FieldList_MouseMove(object s,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed)return;var d=e.GetPosition(FieldList)-dragStart;if(Math.Abs(d.Y)<4)return;if(FieldList.SelectedItem is FieldConfig f)DragDrop.DoDragDrop(FieldList,f,DragDropEffects.Move);}
 void FieldList_Drop(object s,DragEventArgs e){if(!e.Data.GetDataPresent(typeof(FieldConfig)))return;var source=(FieldConfig)e.Data.GetData(typeof(FieldConfig))!;var target=e.OriginalSource as DependencyObject;while(target is not null&&target is not ListBoxItem)target=System.Windows.Media.VisualTreeHelper.GetParent(target);var targetField=(target as ListBoxItem)?.DataContext as FieldConfig;var oldIndex=ViewModel.Config.Fields.IndexOf(source);var newIndex=targetField is null?ViewModel.Config.Fields.Count-1:ViewModel.Config.Fields.IndexOf(targetField);if(oldIndex<0||newIndex<0||oldIndex==newIndex)return;ViewModel.Config.Fields.RemoveAt(oldIndex);if(oldIndex<newIndex)newIndex--;ViewModel.Config.Fields.Insert(newIndex,source);FieldList.Items.Refresh();FieldList.SelectedItem=source;}
 void FieldList_SelectionChanged(object s,SelectionChangedEventArgs e){selected=FieldList.SelectedItem as FieldConfig;BuildEditor();}
 void RenameField(FieldConfig field,string newName){newName=newName.Trim();if(string.IsNullOrWhiteSpace(newName)||newName==field.Name)return;if(ViewModel.Config.Fields.Any(x=>x!=field&&x.Name==newName)){MessageBox.Show("字段名称不能重复。","字段",MessageBoxButton.OK,MessageBoxImage.Warning);return;}var old=field.Name;field.Name=newName;foreach(var g in ViewModel.Config.Groups){if(g.TypedOverrides.TryGetValue(old,out var value)){g.TypedOverrides.Remove(old);g.TypedOverrides[newName]=value;}}FieldList.Items.Refresh();RefreshOverrideMatrix();SaveLastConfig();}
 void BuildEditor(){EditorPanel.Children.Clear();if(selected is null)return;AddText("名称",selected.Name,v=>RenameField(selected,v));switch(selected){case IntField f:AddText("最小值",f.Min,v=>f.Min=v);AddText("最大值",f.Max,v=>f.Max=v);break;case FloatField f:AddText("最小值",f.Min,v=>f.Min=v);AddText("最大值",f.Max,v=>f.Max=v);AddInt("精度",f.Precision,v=>f.Precision=v);break;case StringField f:AddText("固定长度",f.Length,v=>f.Length=v);AddText("最小长度（可选）",f.MinLength??"",v=>f.MinLength=string.IsNullOrWhiteSpace(v)?null:v);AddText("最大长度（可选）",f.MaxLength??"",v=>f.MaxLength=string.IsNullOrWhiteSpace(v)?null:v);AddCombo("填充",new[]{"不选","数字","小写字母","大写字母","大小写字母","数字和大小写字母"},(int)f.CharsetPreset,v=>{f.CharsetPreset=(CharsetPreset)v;f.Charset=PresetCharset(f.CharsetPreset);BuildEditor();});AddText("自定义字符集（可选）",f.Charset,v=>{f.Charset=v;});AddCombo("构造",new[]{"随机","回文","周期","全部相同"},(int)f.Pattern,v=>f.Pattern=(StringPattern)v);break;case ArrayField f:AddCombo("元素类型",new[]{"整数","浮点数","字符串"},(int)f.ElementType,v=>{f.ElementType=(ArrayElementType)v;BuildEditor();});AddText("数组长度",f.Length,v=>f.Length=v);AddCombo("元素分隔",new[]{"空格","换行"},(int)f.Separator,v=>f.Separator=(ArraySeparator)v);AddCombo("特殊性质",new[]{"随机","非递减","严格递增","非递增","严格递减","全部相同"},(int)f.Pattern,v=>f.Pattern=(ArrayPattern)v);if(f.ElementType==ArrayElementType.String){AddText("字符串最小长度",f.StringMinLength,v=>f.StringMinLength=v);AddText("字符串最大长度",f.StringMaxLength,v=>f.StringMaxLength=v);AddCombo("字符集",new[]{"不选","数字","小写字母","大写字母","大小写字母","数字和大小写字母"},(int)f.CharsetPreset,v=>{f.CharsetPreset=(CharsetPreset)v;f.Charset=PresetCharset(f.CharsetPreset);BuildEditor();});AddText("自定义字符集（可选）",f.Charset,v=>f.Charset=v);}else{AddText("元素最小值",f.Min,v=>f.Min=v);AddText("元素最大值",f.Max,v=>f.Max=v);if(f.ElementType==ArrayElementType.Float)AddInt("小数精度",f.Precision,v=>f.Precision=v);AddCheck("去重",f.Unique,v=>f.Unique=v);AddCombo("排序",new[]{"无","升序","降序"},(int)f.SortOrder,v=>f.SortOrder=(ArraySortOrder)v);}break;case TreeField f:AddText("节点数",f.Nodes,v=>f.Nodes=v);AddInt("起始编号",f.IndexStart,v=>f.IndexStart=v);AddInt("根节点",f.Root,v=>f.Root=v);AddCombo("形态",new[]{"随机树","链","菊花","二叉树"},(int)f.Shape,v=>f.Shape=(TreeShape)v);AddCheck("带边权",f.Weighted,v=>f.Weighted=v);AddText("权值下界",f.WeightMin,v=>f.WeightMin=v);AddText("权值上界",f.WeightMax,v=>f.WeightMax=v);break;case GraphField f:AddText("密度（Sparse/Dense）",f.Density.ToString(System.Globalization.CultureInfo.InvariantCulture),v=>{if(double.TryParse(v,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var d))f.Density=Math.Clamp(d,0,1);});AddCombo("特殊结构",new[]{"随机图","链图","菊花图","二叉树","网格图","稀疏图","稠密图"},(int)f.Shape,v=>f.Shape=(GraphSpecialType)v);AddInt("起始编号",f.IndexStart,v=>f.IndexStart=v);AddText("节点数",f.Nodes,v=>f.Nodes=v);AddText("边数",f.Edges,v=>f.Edges=v);AddCheck("有向图",f.Directed,v=>f.Directed=v);AddCheck("连通",f.Connected,v=>f.Connected=v);AddCheck("DAG",f.Dag,v=>f.Dag=v);AddCheck("二分图",f.Bipartite,v=>f.Bipartite=v);AddInt("左部节点数",f.LeftPartSize,v=>f.LeftPartSize=v);AddCheck("允许自环",f.AllowSelfLoops,v=>f.AllowSelfLoops=v);AddCheck("允许重边",f.AllowMultiEdges,v=>f.AllowMultiEdges=v);AddCheck("带边权",f.Weighted,v=>f.Weighted=v);AddText("权值下界",f.WeightMin,v=>f.WeightMin=v);AddText("权值上界",f.WeightMax,v=>f.WeightMax=v);break;}}
 static string PresetCharset(CharsetPreset p)=>p switch{CharsetPreset.Digits=>"0123456789",CharsetPreset.Lowercase=>"abcdefghijklmnopqrstuvwxyz",CharsetPreset.Uppercase=>"ABCDEFGHIJKLMNOPQRSTUVWXYZ",CharsetPreset.Letters=>"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ",CharsetPreset.DigitsAndLetters=>"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ",_=>""};
 void AddText(string label,string value,Action<string> set){EditorPanel.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,4,0,2)});var box=new TextBox{Text=value,Margin=new Thickness(0,0,0,4)};box.TextChanged+=(s,e)=>{if(box.IsKeyboardFocusWithin){set(box.Text);FieldList.Items.Refresh();}};EditorPanel.Children.Add(box);}
 void AddInt(string label,int value,Action<int> set){AddText(label,value.ToString(),v=>{if(int.TryParse(v,out var x))set(x);});}
 void AddCheck(string label,bool value,Action<bool> set){var box=new CheckBox{Content=label,IsChecked=value,Margin=new Thickness(0,4,0,4)};box.Checked+=(s,e)=>set(true);box.Unchecked+=(s,e)=>set(false);EditorPanel.Children.Add(box);}
 void AddCombo(string label,string[] values,int index,Action<int> set){EditorPanel.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,4,0,2)});var box=new ComboBox{ItemsSource=values,SelectedIndex=index,Margin=new Thickness(0,0,0,4)};box.SelectionChanged+=(s,e)=>{if(box.SelectedIndex>=0)set(box.SelectedIndex);};EditorPanel.Children.Add(box);}
}
